var i=class{constructor(){this.set_event()}get elm_main(){return document.querySelector("main.desktop")}set_event(){window.addEventListener("click",this.click.bind(this))}click(e){let n=e.target.closest(".icon");if(n){let t=n.querySelector(".name").textContent;this.view_window({name:t})}if(e.target.closest(".window .header .close")){let t=e.target.closest(".window");t.parentNode.removeChild(t)}}view_window(e){if(this.elm_main.querySelector(`.window[name="${e.name}"]`))return;let n=document.createElement("div");n.className="window",n.name=e.name,n.innerHTML=`<div class="header">
  <span class="name">${e.name}</span>
  <div class="close"></div>
</div>
<div class="body"></div>
`,this.elm_main.appendChild(n)}};switch(document.readyState){case"complete":case"interactive":new i;break;default:window.addEventListener("DOMContentLoaded",()=>new i)}
